import type { Plugin } from "../../kernel/types";

const EVENT = "counter.value";

const plugin: Plugin = {
  id: "event-counter",
  name: "事件计数器",
  version: "1.0.0",
  onLoad(ctx) {
    // 本实例变量：监听器观察到的最新值
    let observed: unknown = undefined;
    let observedCount = 0;

    // 注册 listener 监听 counter.value 事件
    ctx.register({
      kind: "listener",
      listener: {
        event: EVENT,
        handler: (payload: any) => {
          const value = payload && typeof payload === "object" ? payload?.data?.value : undefined;
          observed = value;
          observedCount += 1;
        },
      },
    });

    ctx.register({
      kind: "tool",
      tool: {
        name: "emit_value",
        version: "1.0.0",
        description: "发射 counter.value 事件（值为 27），并返回监听器观察到的值。",
        permissions: { capabilities: [{ kind: "event", name: EVENT }] },
        sideEffect: "write",
        parameters: {
          type: "object",
          properties: {
            value: { type: "number", description: "要发射的值，默认 27" },
          },
        },
        outputSchema: {
          type: "object",
          properties: {
            ok: { type: "boolean" },
            data: {
              type: "object",
              properties: {
                emitted: { type: "number" },
                event: { type: "string" },
                observed: {},
                observedCount: { type: "number" },
              },
            },
          },
        },
        async handler(args: any, tctx: any) {
          const value = typeof args?.value === "number" ? args.value : 27;

          // 发射前重置观察状态
          observed = undefined;
          observedCount = 0;

          const emitPayload = { data: { value } };
          let emitVia = "none";

          // 优先尝试宿主 emit 工具（通过 ToolContext.invoke）
          try {
            const res = await tctx.invoke("emit", { event: EVENT, ...emitPayload });
            if (res && (res as any).ok !== false) emitVia = "tool:emit";
          } catch {
            /* 宿主 emit 工具不可用，回退 */
          }

          // 回退：ctx.emit / tctx.emit
          if (emitVia === "none") {
            const emitter = (ctx as any).emit || (tctx as any).emit;
            if (typeof emitter === "function") {
              emitter.call(emitter === (ctx as any).emit ? ctx : tctx, EVENT, emitPayload);
              emitVia = emitter === (ctx as any).emit ? "ctx.emit" : "tctx.emit";
            }
          }

          // 让出控制权，确保监听器回调先执行
          await new Promise((r) => setTimeout(r, 0));

          return {
            ok: true,
            data: {
              emitted: value,
              event: EVENT,
              observed,
              observedCount,
              emitVia,
            },
          };
        },
      },
    });
  },
};

export default plugin;

